export type AuthenticatedUser = {
  id: string
  full_name: string
  email: string
  role: 'customer' | 'admin'
}

export type LoginResult = {
  access_token: string
  token_type: 'bearer'
  user: AuthenticatedUser
}

type LoginInput = {
  email: string
  password: string
}

const apiBaseUrl = import.meta.env.VITE_API_URL ?? 'http://localhost:8000/api'

export async function login(input: LoginInput): Promise<LoginResult> {
  const response = await fetch(`${apiBaseUrl}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as {
      error?: { message?: string }
    } | null
    throw new Error(payload?.error?.message ?? 'We could not sign you in. Please try again.')
  }

  return (await response.json()) as LoginResult
}

import type { LoginResult } from './api/authApi'

const sessionStorageKey = 'aretiva.session'

export function saveSession(session: LoginResult): void {
  localStorage.setItem(sessionStorageKey, JSON.stringify(session))
}

export function readSession(): LoginResult | null {
  const rawSession = localStorage.getItem(sessionStorageKey)
  if (!rawSession) {
    return null
  }

  try {
    return JSON.parse(rawSession) as LoginResult
  } catch {
    localStorage.removeItem(sessionStorageKey)
    return null
  }
}

export function clearSession(): void {
  localStorage.removeItem(sessionStorageKey)
}

